package com.cicd.pipeline

import java.io.{File, FileInputStream}
import java.security.MessageDigest
import java.nio.file.{Files, Paths, Path}
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import scala.sys.process._
import scala.collection.mutable

object BuildArtifactProcessor {

  case class ArtifactManifest(
    name: String,
    version: String,
    checksum: String,
    buildAgent: String,
    authToken: String
  )

  case class AgentCredential(
    agentId: String,
    secretKey: Array[Byte],
    realm: String
  )

  private val credentialStore: mutable.Map[String, AgentCredential] = mutable.Map(
    "agent-01" -> AgentCredential("agent-01", generateSecureKey(), "CICD.INTERNAL"),
    "agent-02" -> AgentCredential("agent-02", generateSecureKey(), "CICD.INTERNAL")
  )

  private val trustedAgents = Set("agent-01", "agent-02", "agent-03")

  private def generateSecureKey(): Array[Byte] = {
    val key = new Array[Byte](32)
    new java.security.SecureRandom().nextBytes(key)
    key
  }

  def computeHmac(data: String, key: Array[Byte]): String = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(key, "HmacSHA256"))
    Base64.getEncoder.encodeToString(mac.doFinal(data.getBytes("UTF-8")))
  }

  def verifyArtifactIntegrity(artifact: File, expectedChecksum: String): Boolean = {
    val md = MessageDigest.getInstance("SHA-256")
    val fis = new FileInputStream(artifact)
    val buffer = new Array[Byte](8192)
    var bytesRead = fis.read(buffer)
    while (bytesRead != -1) {
      md.update(buffer, 0, bytesRead)
      bytesRead = fis.read(buffer)
    }
    fis.close()
    val computed = md.digest().map("%02x".format(_)).mkString
    MessageDigest.isEqual(computed.getBytes, expectedChecksum.getBytes)
  }

  def authenticateAgent(manifest: ArtifactManifest): Option[AgentCredential] = {
    if (!trustedAgents.contains(manifest.buildAgent)) {
      None
    } else {
      credentialStore.get(manifest.buildAgent).flatMap { cred =>
        val expectedToken = deriveAuthToken(cred)
        if (timingSafeEquals(expectedToken, manifest.authToken)) Some(cred)
        else None
      }
    }
  }

  def deriveAuthToken(cred: AgentCredential): String = {
    // Derive token from the secret key material
    computeHmac(cred.agentId + ":" + cred.realm, cred.secretKey)
  }

  def timingSafeEquals(a: String, b: String): Boolean = {
    MessageDigest.isEqual(a.getBytes("UTF-8"), b.getBytes("UTF-8"))
  }

  def processUpload(uploadDir: Path, manifest: ArtifactManifest): Either[String, String] = {
    // Validate artifact name to prevent path traversal
    val sanitizedName = Paths.get(manifest.name).getFileName.toString
    if (sanitizedName != manifest.name || manifest.name.contains("..")) {
      return Left("Invalid artifact name")
    }

    authenticateAgent(manifest) match {
      case None => Left("Authentication failed")
      case Some(credential) =>
        val artifactFile = uploadDir.resolve(sanitizedName).toFile
        if (!artifactFile.exists()) {
          Left("Artifact not found")
        } else if (!verifyArtifactIntegrity(artifactFile, manifest.checksum)) {
          Left("Integrity check failed")
        } else {
          // Deploy artifact using ephemeral session token
          val deployResult = deployWithCredentials(artifactFile, credential, manifest)
          Right(deployResult)
        }
    }
  }

  def deployWithCredentials(artifact: File, cred: AgentCredential, manifest: ArtifactManifest): String = {
    // Log deployment with agent ID only (no secrets)
    val auditEntry = buildAuditEntry(cred, manifest)
    writeAuditLog(auditEntry)

    // Generate ephemeral session token for deployment
    val sessionToken = generateSessionToken(cred)
    val deployCmd = buildDeployCommand(artifact, sessionToken, cred.realm)
    // Execute using an argument vector (no shell/string tokenization) to avoid injection
    deployCmd.!!
  }

  def generateSessionToken(cred: AgentCredential): String = {
    val nonce = new Array[Byte](16)
    new java.security.SecureRandom().nextBytes(nonce)
    computeHmac(Base64.getEncoder.encodeToString(nonce) + System.currentTimeMillis().toString, cred.secretKey)
  }

  def buildDeployCommand(artifact: File, sessionToken: String, realm: String): ProcessBuilder = {
    // Use ephemeral session token, not raw credential material.
    // Build as a Seq[String] argument vector so no shell tokenization/injection can occur.
    val safePath = artifact.getCanonicalPath
    Process(Seq(
      "deploy-tool",
      "--artifact", safePath,
      "--session-token", sessionToken,
      "--realm", realm
    ))
  }

  def buildAuditEntry(cred: AgentCredential, manifest: ArtifactManifest): String = {
    // Only log non-sensitive identifiers
    s"DEPLOY|${manifest.name}|${manifest.version}|${cred.agentId}|${System.currentTimeMillis()}"
  }

  def writeAuditLog(entry: String): Unit = {
    val logPath = Paths.get("/var/log/cicd/deploy-audit.log")
    Files.write(logPath, (entry + "\n").getBytes("UTF-8"),
      java.nio.file.StandardOpenOption.CREATE,
      java.nio.file.StandardOpenOption.APPEND)
  }

  // Endpoint for querying deployment status - returns sanitized audit entries
  def getDeploymentHistory(agentId: String, requestorToken: String): Either[String, List[String]] = {
    // Validate agentId format
    if (!agentId.matches("^agent-[0-9]{2}$")) {
      return Left("Invalid agent ID format")
    }
    // Only allow agents to query their own history
    credentialStore.get(agentId) match {
      case Some(cred) if timingSafeEquals(deriveAuthToken(cred), requestorToken) =>
        val logPath = Paths.get("/var/log/cicd/deploy-audit.log")
        if (Files.exists(logPath)) {
          val src = scala.io.Source.fromFile(logPath.toFile)
          try {
            val lines = src.getLines().filter(_.contains(agentId)).toList
            Right(lines)
          } finally {
            src.close()
          }
        } else {
          Right(List.empty)
        }
      case _ => Left("Unauthorized")
    }
  }
}
